from typing import List, Tuple

def rolling_max(numbers: List[int]) -> List[int]:
    if not numbers:
        return []

    rolling_max_values = []
    window = []

    for i, num in enumerate(numbers):
        if i >= 3:
            window.pop(0)
        window.append(num)
        rolling_max_values.append(max(window))

    return rolling_max_values
from typing import List, Tuple


def rolling_max(numbers: List[int]) -> List[int]:
    result = []
    k = 3  # window size
    max_val = max(numbers[:k])
    result.append(max_val)

    for i in range(k, len(numbers)):
        if numbers[i] >= max_val:
            max_val = numbers[i]
        else:
            if numbers[i - k] == max_val:
                max_val = max(numbers[i - k + 1:i + 1])
        result.append(max_val)

    return result
