def count_distinct_characters(string: str) -> int:
    # Step 1: Analyze the input
    string = string.lower()  # Convert the input string to lowercase to ignore case sensitivity.

    # Step 2: Count distinct characters
    distinct_chars = set()
    for char in string:
        if char.isalpha():  # Consider only alphabetic characters
            distinct_chars.add(char)

    # Step 3: Return the count
    return len(distinct_chars)  # Return the size of the set as the count of distinct characters.

